/// A solid glyph at the panes' 14 px size.
#[component]
pub fn Fa(icon: Icon) -> impl IntoView {
    let (view_box, src) = icon.svg();
    view! {
        <svg viewBox=view_box width="14" height="14" fill="currentColor" inner_html=src></svg>
    }
}
